<template>
  <div>
    <div class="mb-3 flex items-center justify-between gap-2">
      <div class="flex min-w-0 items-center gap-2">
        <h3 class="truncate text-sm font-semibold text-navy-900 dark:text-gray-100">{{ field.label }}</h3>
        <span :class="ui.COUNT_BADGE">{{ rows.length }}</span>
      </div>
      <button type="button" :class="[ui.BTN_SECONDARY, '!h-8 flex-shrink-0 !px-2.5']" @click="addRow">
        <LucideIcon name="plus" class="h-4 w-4 text-forest-700 dark:text-forest-300" />
        Add Row
      </button>
    </div>

    <p v-if="!rows.length" :class="[ui.EMPTY_STATE, '!py-6']">No rows yet.</p>

    <template v-else>
      <!-- Desktop / tablet: a compact grid like Desk's - a few key columns,
      the rest behind the row editor. -->
      <div class="hidden overflow-x-auto rounded-lg ring-1 ring-gray-200 dark:ring-gray-800 sm:block">
        <table class="w-full border-collapse text-left text-sm">
          <thead class="bg-gray-50 text-xs uppercase tracking-wide text-gray-500 dark:bg-gray-800 dark:text-gray-400">
            <tr>
              <th class="w-10 whitespace-nowrap border-b px-3 py-2 dark:border-gray-800">#</th>
              <th v-for="col in summaryColumns" :key="col.fieldname" class="whitespace-nowrap border-b px-3 py-2 dark:border-gray-800">
                {{ col.label }}
              </th>
              <th v-if="statusColumn" class="whitespace-nowrap border-b px-3 py-2 dark:border-gray-800">{{ statusColumn.label }}</th>
              <th class="w-20 border-b dark:border-gray-800"></th>
            </tr>
          </thead>
          <tbody>
            <tr
              v-for="(row, idx) in rows"
              :key="keyOf(row)"
              class="cursor-pointer hover:bg-forest-50/60 dark:hover:bg-gray-800"
              @click="openRow(idx)"
            >
              <td class="whitespace-nowrap border-b px-3 py-2 text-gray-500 dark:border-gray-800 dark:text-gray-400">{{ idx + 1 }}</td>
              <td
                v-for="col in summaryColumns"
                :key="col.fieldname"
                class="whitespace-nowrap border-b px-3 py-2 text-gray-900 dark:border-gray-800 dark:text-gray-100"
              >
                <span v-if="isEmptyValue(row[col.fieldname])" class="text-gray-300 dark:text-gray-600">—</span>
                <template v-else>{{ formatFieldValue(row[col.fieldname], col) }}</template>
              </td>
              <td v-if="statusColumn" class="whitespace-nowrap border-b px-3 py-2 dark:border-gray-800">
                <span v-if="!isEmptyValue(row[statusColumn.fieldname])" :class="[ui.PILL, ui.TONE[toneFor(row[statusColumn.fieldname])]]">
                  {{ row[statusColumn.fieldname] }}
                </span>
              </td>
              <td class="border-b px-2 py-1.5 text-right dark:border-gray-800" @click.stop>
                <div class="flex items-center justify-end gap-1">
                  <button type="button" :class="ICON_BTN" :aria-label="`Edit row ${idx + 1}`" title="Edit row" @click="openRow(idx)">
                    <LucideIcon name="pencil" class="h-4 w-4" />
                  </button>
                  <button type="button" :class="ICON_BTN" :aria-label="`Remove row ${idx + 1}`" title="Remove row" @click="confirmRemoveRow(idx)">
                    <LucideIcon name="trash-2" class="h-4 w-4" />
                  </button>
                </div>
              </td>
            </tr>
          </tbody>
        </table>
      </div>

      <!-- Phone: one card per row - a 3-column table doesn't fit ~310px
      without sideways scrolling, which also hid the edit / remove buttons
      off screen. Tap the card to edit; remove stays one tap away. -->
      <div class="space-y-2 sm:hidden">
        <div
          v-for="(row, idx) in rows"
          :key="keyOf(row)"
          role="button"
          tabindex="0"
          class="rounded-lg bg-white p-3 ring-1 ring-gray-200 active:bg-forest-50 dark:bg-gray-900 dark:ring-gray-800"
          @click="openRow(idx)"
          @keydown.enter="openRow(idx)"
        >
          <div class="flex items-center justify-between gap-2">
            <div class="flex min-w-0 items-center gap-2">
              <span class="rounded-md bg-gray-100 px-1.5 py-0.5 text-xs font-semibold text-gray-600 dark:bg-gray-800 dark:text-gray-300">Row {{ idx + 1 }}</span>
              <span
                v-if="statusColumn && !isEmptyValue(row[statusColumn.fieldname])"
                :class="[ui.PILL, ui.TONE[toneFor(row[statusColumn.fieldname])], 'truncate']"
              >
                {{ row[statusColumn.fieldname] }}
              </span>
            </div>
            <div class="flex flex-shrink-0 items-center gap-1" @click.stop>
              <button type="button" :class="ICON_BTN" :aria-label="`Edit row ${idx + 1}`" @click="openRow(idx)">
                <LucideIcon name="pencil" class="h-4 w-4" />
              </button>
              <button type="button" :class="ICON_BTN" :aria-label="`Remove row ${idx + 1}`" @click="confirmRemoveRow(idx)">
                <LucideIcon name="trash-2" class="h-4 w-4" />
              </button>
            </div>
          </div>
          <dl class="mt-2 grid grid-cols-2 gap-x-3 gap-y-2">
            <div v-for="col in summaryColumns" :key="col.fieldname" class="min-w-0">
              <dt class="truncate text-[11px] text-gray-500 dark:text-gray-400">{{ col.label }}</dt>
              <dd class="truncate text-sm font-medium text-gray-900 dark:text-gray-100">
                <span v-if="isEmptyValue(row[col.fieldname])" class="font-normal text-gray-300 dark:text-gray-600">—</span>
                <template v-else>{{ formatFieldValue(row[col.fieldname], col) }}</template>
              </dd>
            </div>
          </dl>
        </div>
      </div>
    </template>

    <Dialog v-model="showRowEditor" :options="{ title: `${field.label} - Row ${(editingIdx ?? 0) + 1}`, size: 'xl' }">
      <template #body-content>
        <div v-if="editingRow" class="grid grid-cols-1 gap-4">
          <DynamicField
            v-for="col in columns"
            :key="col.fieldname"
            :field="col"
            :doctype="doctype"
            :docname="docname"
            v-model="editingRow[col.fieldname]"
          />
        </div>
      </template>
      <template #actions>
        <Button variant="solid" class="w-full" @click="showRowEditor = false">
          Done
        </Button>
      </template>
    </Dialog>

    <Dialog
      v-model="showRemoveConfirm"
      :options="{
        title: 'Remove row?',
        message: 'This row will be removed once you save the form. This cannot be undone.',
        icon: { name: 'alert-triangle', appearance: 'danger' },
        actions: [
          { label: 'Remove', variant: 'solid', theme: 'red', onClick: doRemoveRow },
          { label: 'Cancel' },
        ],
      }"
    />
  </div>
</template>

<script setup>
import { computed, ref } from 'vue'
import { Button, Dialog } from 'frappe-ui'
import DynamicField from '@/components/DynamicField.vue'
import LucideIcon from '@/components/LucideIcon.vue'
import { useMeta, useFormFields } from '@/data/useMeta'
import { isEmptyValue, formatFieldValue, toneFor } from '@/data/recordFormat'
import * as ui from '@/data/ui'

const { field, modelValue, doctype, docname } = defineProps({
  field: { type: Object, required: true },
  modelValue: { type: Array, default: () => [] },
  doctype: { type: String, default: null },
  docname: { type: String, default: null },
})
const emit = defineEmits(['update:modelValue'])

const ICON_BTN =
  'flex h-8 w-8 items-center justify-center rounded-md text-gray-400 hover:bg-gray-100 hover:text-navy-900 dark:hover:bg-gray-800 dark:hover:text-gray-200'

const childMetaResource = useMeta(field.options)
const columns = useFormFields(childMetaResource)

// A "status" field (Pending / Completed on the visit tables) is what tells
// rows apart at a glance - shown as a pill, not as one of the columns.
const statusColumn = computed(() => columns.value.find((c) => c.fieldname === 'status' && c.fieldtype === 'Select') || null)

// The row summary only needs enough columns to identify the row - matching
// Desk's grid, which shows a handful of in_list_view fields and pushes the
// rest behind the row-edit dialog. Wide child tables (10+ fields) are
// unusable as an all-columns-inline table.
const summaryColumns = computed(() => {
  const candidates = columns.value.filter((c) => c !== statusColumn.value)
  const inListView = candidates.filter((c) => c.in_list_view)
  // Four values fill the phone card's 2 x 2 grid; three when a status pill
  // is shown too, so the desktop table keeps the same width.
  return (inListView.length ? inListView : candidates).slice(0, statusColumn.value ? 3 : 4)
})

const rows = computed({
  get: () => modelValue || [],
  set: (v) => emit('update:modelValue', v),
})

// A stable key per row: saved rows have a `name`, but the old `__key` was
// only set on rows added here, so every loaded row shared key `undefined`
// and removing one could redraw the wrong row. A WeakMap gives each row
// object its own key without adding a field that would be sent on save.
const rowKeys = new WeakMap()
let rowKeyCounter = 0
function keyOf(row) {
  if (row.name) return row.name
  if (!rowKeys.has(row)) rowKeys.set(row, `new-${rowKeyCounter++}`)
  return rowKeys.get(row)
}

function addRow() {
  // Mutate the array in place (it's the same reactive array the parent form
  // owns) rather than reassigning through the computed setter - reassigning
  // round-trips through the parent via emit('update:modelValue', ...), and
  // reading rows.value.length right after that in the same tick can still
  // see the pre-update array, opening the row editor on the wrong (stale)
  // index.
  const newRow = {}
  rows.value.push(newRow)
  openRow(rows.value.length - 1)
}

const showRowEditor = ref(false)
const editingIdx = ref(null)
const editingRow = computed(() => (editingIdx.value == null ? null : rows.value[editingIdx.value]))

function openRow(idx) {
  editingIdx.value = idx
  showRowEditor.value = true
}

const showRemoveConfirm = ref(false)
const pendingRemoveIdx = ref(null)

function confirmRemoveRow(idx) {
  pendingRemoveIdx.value = idx
  showRemoveConfirm.value = true
}

function doRemoveRow(close) {
  rows.value = rows.value.filter((_, i) => i !== pendingRemoveIdx.value)
  pendingRemoveIdx.value = null
  close()
}
</script>
